import{_ as e,b as r,e as t,a7 as o}from"./chunks/framework.CFO60l-h.js";const u=JSON.parse('{"title":"师姐/兄说","description":"从已有分享材料中整理学习与升学经验，也为新的经验分享提供提纲。","frontmatter":{"title":"师姐/兄说","description":"从已有分享材料中整理学习与升学经验，也为新的经验分享提供提纲。"},"headers":[],"relativePath":"voices.md","filePath":"voices.md","lastUpdated":null}'),i={name:"voices.md"};function l(n,a,s,h,p,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="师姐-兄说" tabindex="-1">师姐 / 兄说 <a class="header-anchor" href="#师姐-兄说" aria-label="Permalink to &quot;师姐 / 兄说&quot;">​</a></h1><p>每个人的背景、兴趣和选择都不同。这里把现有经验材料整理成可以行动的小建议，帮助你找到适合自己的节奏。</p><blockquote><p>以下为现有保研经验分享材料的编辑整理，不是新增访谈或逐字引语。完整内容见<a href="./baoyan/experiences">保研经验分享</a>。</p></blockquote><h2 id="学习-先建立自己的问题清单" tabindex="-1">学习：先建立自己的问题清单 <a class="header-anchor" href="#学习-先建立自己的问题清单" aria-label="Permalink to &quot;学习：先建立自己的问题清单&quot;">​</a></h2><p>阅读时，可以围绕三个问题记笔记：作者在回答什么问题？用了什么证据？我能想到什么不同的例子？与其抄写整段原文，不如用自己的话概括观点，并保留页码和出处。</p><ul><li>课前：查看章节主题，写下最想解决的一个问题。</li><li>课中：记录老师强调的概念及其联系，而非只记结论。</li><li>课后：从一则新闻中找案例，尝试用刚学的概念解释。</li><li>复习：把概念、论点、案例整理成一页提纲，再检查薄弱环节。</li></ul><p>从<a href="./courses/news-intro">新闻学概论阅读材料</a>和<a href="./courses/english-commentary">英语新闻评论资料</a>开始实践。</p><h2 id="国际传播-把经历连成线" tabindex="-1">国际传播：把经历连成线 <a class="header-anchor" href="#国际传播-把经历连成线" aria-label="Permalink to &quot;国际传播：把经历连成线&quot;">​</a></h2><p>现有国新方向经验强调全流程模拟面试，包含中文与英文。整理项目经历时，说明自己的角色、具体工作、结果和反思，并把这些经历与一个持续的兴趣连接起来。</p><p><strong>现在可以做</strong>：选择一段最熟悉的经历，分别准备一段中文介绍和一段英文介绍，录音回听，检查是否有具体事实。</p><h2 id="学术研究-给知识一个自己的角度" tabindex="-1">学术研究：给知识一个自己的角度 <a class="header-anchor" href="#学术研究-给知识一个自己的角度" aria-label="Permalink to &quot;学术研究：给知识一个自己的角度&quot;">​</a></h2><p>本院学硕经验建议尽早启动复习、每周复盘。面试中与其面面俱到，更适合选择一个角度深入，展示自己的研究问题与思考过程。</p><p><strong>现在可以做</strong>：从最近的阅读中提出一个研究问题，写清研究对象、已有解释、还想知道什么。暂时没有答案也可以继续积累。</p><h2 id="外校申请-提前读懂目标项目" tabindex="-1">外校申请：提前读懂目标项目 <a class="header-anchor" href="#外校申请-提前读懂目标项目" aria-label="Permalink to &quot;外校申请：提前读懂目标项目&quot;">​</a></h2><p>外保经验关注学业、科研与专业背景。研究过程和逻辑需要能够讲清楚；不同项目的要求与考核形式各异，应分别核对。</p><p><strong>现在可以做</strong>：为感兴趣的项目建一份清单，记录官方信息来源、申请时间、材料要求与待核实问题。项目门槛与日期以当年正式通知为准。</p><h2 id="分享你自己的经验" tabindex="-1">分享你自己的经验 <a class="header-anchor" href="#分享你自己的经验" aria-label="Permalink to &quot;分享你自己的经验&quot;">​</a></h2><p>可以在<a href="./upload">上传资料</a>页面预览投稿流程（当前不发送文件）。你也可以先用这份提纲整理文字，待后端接入后提交：</p><ol><li><strong>背景与目标</strong>：当时处于什么阶段，想解决什么问题？</li><li><strong>准备过程</strong>：按时间记录实际做过的事，标明哪些方法最有帮助。</li><li><strong>具体例子</strong>：选一段阅读、一次课程项目或一次准备经历，说明如何推进。</li><li><strong>踩过的坑</strong>：哪些事情可以更早做，哪些方法不适合自己？</li><li><strong>适用范围</strong>：写明年份、方向与信息来源，区分个人感受与正式要求。</li><li><strong>隐私与版权</strong>：去除姓名、学号、联系方式和未获授权的他人材料。</li></ol><h2 id="继续查阅" tabindex="-1">继续查阅 <a class="header-anchor" href="#继续查阅" aria-label="Permalink to &quot;继续查阅&quot;">​</a></h2><ul><li><a href="./baoyan/timeline">保研时间线</a>：按阶段安排准备。</li><li><a href="./baoyan/interview">笔试与面试</a>：了解题型与训练方式。</li><li><a href="./baoyan/faq">保研常见问题</a>：核对容易混淆的问题。</li><li><a href="./programs/">培养方案</a>：回到自己的课程与学分规划。</li></ul>',21)])])}const f=e(i,[["render",l]]);export{u as __pageData,f as default};
